import numpy as np, json
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares
from scipy.linalg import logm

def skew(x): return np.array([[0,-x[2],x[1]],[x[2],0,-x[0]],[-x[1],x[0],0]])
def twist_exp(s,t):
 w=s[:3]; v=s[3:]; n=np.linalg.norm(w); w=w/n; t=t*n; v=v/n
 W=skew(w); R=Rot.from_rotvec(w*t).as_matrix()
 T=np.eye(4); T[:3,:3]=R; T[:3,3]=(np.eye(3)*t+(1-np.cos(t))*W+(t-np.sin(t))*W@W)@v
 return T
class Arm:
 def __init__(self,side):
  self.side=side; self.offset=0 if side=='left' else 7; cam='wrist_cam_'+side
  records=json.load(open('/app/output/calibration.json')); self.q0=np.array(records[0]['q'])[self.offset:self.offset+6]
  self.T0=np.array(records[0]['cameras'][cam]['cam2world_gl'])
  S=[]
  for i in range(6):
   T=np.array(records[i+1]['cameras'][cam]['cam2world_gl']); dq=records[i+1]['q'][self.offset+i]-self.q0[i]
   L=logm(T@np.linalg.inv(self.T0)).real/dq
   S.append(np.r_[L[2,1],L[0,2],L[1,0],L[:3,3]])
  self.S=np.array(S)
  def err(x):
   self.S=x.reshape(6,6); e=[]
   for r in records[1:]:
    q=np.array(r['q'])[self.offset:self.offset+6]; obs=np.array(r['cameras'][cam]['cam2world_gl']); pred=self.fk(q)
    e.extend((pred[:3,3]-obs[:3,3])*3); e.extend(Rot.from_matrix(pred[:3,:3]@obs[:3,:3].T).as_rotvec())
   return e
  fit=least_squares(err,self.S.flatten(),max_nfev=300,gtol=1e-12,ftol=1e-12,xtol=1e-12)
  self.S=fit.x.reshape(6,6)
 def fk(self,q):
  T=np.eye(4)
  for s,t in zip(self.S,np.array(q)-self.q0): T=T@twist_exp(s,t)
  return T@self.T0
 def ik(self,T,q):
  lo=np.array([-3.14158,-1.85005,-1.76278,-3.14158,-1.8675,-3.14158]); hi=np.array([3.14158,1.25664,1.6057,3.14158,2.23402,3.14158])
  def err(q):
   p=self.fk(q); return np.r_[(p[:3,3]-T[:3,3])*4,Rot.from_matrix(p[:3,:3]@T[:3,:3].T).as_rotvec()]
  fit=least_squares(err,np.clip(q,lo+1e-5,hi-1e-5),bounds=(lo,hi),max_nfev=400,gtol=1e-11,ftol=1e-11,xtol=1e-11)
  return fit.x,np.linalg.norm(fit.fun)
if __name__=='__main__':
