 mount=np.linalg.inv(a.base@local(q0))@np.array(init['cameras'][cam]['cam2world_gl'])
 return a.base@local(q)@mount

def getcloud(path,cam):
 m=json.load(open(path+'/meta.json'));im=np.array(Image.open(path+'/'+cam+'.png'));d=np.load(path+'/depth_'+cam+'.npy').astype(float)[-1];v,u=np.indices(d.shape);K=np.array(m['cameras'][cam]['intrinsic_cv']);T=camera_pose(m,cam)
 p=np.stack([(u-K[0,2]+.5)*d/K[0,0],-(v-K[1,2]+.5)*d/K[1,1],-d],-1)@T[:3,:3].T+T[:3,3]
 return im,d,p

