import cv2,sys
from perceive import *
def maskcolor(im,name):
 if name=='blue':return (im[:,:,2]>100)&(im[:,:,2]>im[:,:,0]*1.8)&(im[:,:,2]>im[:,:,1]*1.8)
 return (im[:,:,0]>100)&(im[:,:,0]>im[:,:,1]*1.8)&(im[:,:,0]>im[:,:,2]*1.8)
def plane(pts,axis):
 rng=np.random.default_rng(4);best=None;N=len(pts)
 for _ in range(2000):
  sel=pts[rng.choice(N,3,replace=False)];normal=np.cross(sel[1]-sel[0],sel[2]-sel[0]);normal/=np.linalg.norm(normal)+1e-15
  if abs(normal[axis])<.97:continue
  dist=abs((pts-sel[0])@normal);inl=dist<.0015
  if best is None or inl.sum()>best.sum():best=inl
 if best is None:return None
 for _ in range(3):
  cen=pts[best].mean(0);_,_,V=np.linalg.svd(pts[best]-cen);n=V[-1];best=abs((pts-cen)@n)<.0015
 if n[axis]<0:n=-n
 return n,np.dot(n,cen),len(pts[best])
def fit(path):
 for name in ['blue','red']:
  for cam in ['overhead_cam','teleoperator_pov']:
   im,d,p=getcloud(path,cam);mask=maskcolor(im,name);pts=p[mask];pts=pts[(pts[:,2]>.15)&(pts[:,2]<.24)]
   print(cam,name,len(pts),'bounds',np.quantile(pts,[.05,.5,.95],axis=0))
   for axis in [1,2]:print('plane',axis,plane(pts,axis))
if __name__=='__main__':fit('/app/output/'+sys.argv[1])
